 class="button primary small-button" type="submit">Pinjam hari ini</button></form><?php elseif (!$loan && $openLoan): ?><span class="badge warning">Kembalikan hari sebelumnya</span><?php elseif (!$loan && $request->completed_at): ?><span class="badge info">Tidak digunakan</span><?php elseif (!$loan && $date<date('Y-m-d')): ?><span class="badge warning">Belum dicatat</span><?php elseif (!$loan): ?><span class="badge info">Terjadwal</span><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
